<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;use App\Services\ProjectionSettingsService;use App\Services\ProjectionLayoutService;use App\Services\CountryFlagService;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);$type=(string)($_GET['type']??'scoring');$place=(string)($_GET['place']??'');$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id");$s->execute(['id'=>$roundId]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Round not found.');}$settings=ProjectionSettingsService::get($pdo,$roundId,false);$format=(string)($_GET['format']??$settings['screen_format']);$density=(string)($_GET['density']??$settings['density']);$width=(int)($_GET['width']??$settings['custom_width']??0);$height=(int)($_GET['height']??$settings['custom_height']??0);$items=[];$title='';if($type==='judges'){$title='JUDGES';$s=$pdo->prepare("SELECT judge_name,judge_order,is_chief,scoring_scope FROM bdc_scoring_judges WHERE round_id=:r ORDER BY judge_order");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif($type==='competitors'){$title='COMPETITORS';$s=$pdo->prepare("SELECT se.display_name,se.bib_number,se.dance_role,c.country,c.photo_url FROM bdc_scoring_entries se LEFT JOIN bdc_competitors c ON c.id=se.competitor_id WHERE se.round_id=:r AND se.entry_status='active' ORDER BY se.dance_role,se.bib_number IS NULL,se.bib_number,se.display_name");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif(in_array($type,['callbacks','finalists'],true)){$title=$type==='callbacks'?'CALLBACKS':'FINALISTS';$s=$pdo->prepare("SELECT se.display_name,se.bib_number,se.dance_role,c.country,c.photo_url,sr.rank_number FROM bdc_scoring_results sr JOIN bdc_scoring_entries se ON se.id=sr.entry_id LEFT JOIN bdc_competitors c ON c.id=se.competitor_id WHERE sr.round_id=:r AND sr.result_status IN('callback','alternate') ORDER BY sr.rank_number");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();}elseif(in_array($type,['winners','results'],true)){$title=$type==='winners'?'WINNERS':'FINAL RANKING';$s=$pdo->prepare("SELECT fr.final_rank,le.display_name leader_name,fe.display_name follower_name FROM bdc_scoring_final_results fr JOIN bdc_scoring_final_pairs fp ON fp.id=fr.pair_id JOIN bdc_scoring_entries le ON le.id=fp.leader_entry_id LEFT JOIN bdc_scoring_entries fe ON fe.id=fp.follower_entry_id WHERE fr.round_id=:r AND fr.final_rank<=5 ORDER BY fr.final_rank");$s->execute(['r'=>$roundId]);$items=$s->fetchAll();if($place!==''&&$place!=='all')$items=array_values(array_filter($items,fn($x)=>(int)$x['final_rank']===(int)$place));}else{$title='SCORING IN PROGRESS';$s=$pdo->prepare("SELECT COUNT(*) total,SUM(CASE WHEN s.status='submitted' THEN 1 ELSE 0 END) submitted FROM bdc_scoring_judges j LEFT JOIN bdc_scoring_judge_sessions s ON s.judge_id=j.id WHERE j.round_id=:r");$s->execute(['r'=>$roundId]);$items=[$s->fetch()?:['total'=>0,'submitted'=>0]];}$layout=ProjectionLayoutService::resolve($format,max(1,count($items)),$density,$width?:null,$height?:null);$ratio=$layout['ratio'];$cols=$layout['columns'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#000;color:#fff;font-family:Arial,sans-serif;overflow:hidden}.viewport{width:100vw;height:100vh;display:flex;align-items:center;justify-content:center}.stage{aspect-ratio:<?=e((string)$ratio)?>;width:min(100vw,calc(100vh * <?=e((string)$ratio)?>));height:min(100vh,calc(100vw / <?=e((string)$ratio)?>));background:radial-gradient(circle at top,#4a101e,#111827 50%,#030509);padding:2.4%;text-align:center;overflow:hidden;display:flex;flex-direction:column}.event{font-size:clamp(18px,1.8vw,46px);font-weight:900;line-height:1.05}.meta{font-size:clamp(12px,.95vw,24px);color:#ffb7c3;margin-top:.45%;letter-spacing:.08em}.title{font-size:clamp(22px,2.2vw,54px);font-weight:900;margin:1.1% 0 1.4%;line-height:1.05}.list{flex:1;display:grid;grid-template-columns:repeat(<?=$cols?>,minmax(0,1fr));grid-auto-rows:minmax(0,1fr);gap:.7%;min-height:0}.item{background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.2);border-radius:10px;padding:3%;display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;overflow:hidden;font-size:clamp(11px,1.2vw,28px)}.photo{width:min(7vw,9vh);height:min(7vw,9vh);border-radius:50%;object-fit:cover;margin-bottom:.4em;background:#222}.name{font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}.flag{font-size:1.35em;vertical-align:middle}.place{font-size:clamp(28px,4vw,90px);font-weight:900;color:#ffd966}.big{font-size:clamp(60px,10vw,220px);font-weight:900}.small{font-size:.72em;color:#cbd5e1;margin-top:.25em}</style></head><body><div class="viewport"><div class="stage"><div class="event"><?=e($r['event_name'])?></div><div class="meta"><?=e(strtoupper(str_replace('_',' ',$r['division'])))?> · <?=e(strtoupper($r['round_type']))?></div><div class="title"><?=e($title)?></div><div class="list"><?php if($type==='scoring'):$x=$items[0];?><div class="item"><div class="big"><?=(int)($x['submitted']??0)?> / <?=(int)($x['total']??0)?></div><div class="small">JUDGES SUBMITTED</div></div><?php elseif($type==='judges'):foreach($items as $x):?><div class="item"><div class="name"><?=e($x['judge_name'])?><?=(int)$x['is_chief']?' ★':''?></div><div class="small"><?=e(strtoupper($x['scoring_scope']))?></div></div><?php endforeach;elseif(in_array($type,['winners','results'],true)):foreach($items as $x):?><div class="item"><div class="place">#<?=(int)$x['final_rank']?></div><div class="name"><?=e($x['leader_name'])?><?=!empty($x['follower_name'])?' & '.e($x['follower_name']):''?></div></div><?php endforeach;else:foreach($items as $x):$flag=CountryFlagService::emoji($x['country']??null);?><div class="item"><?php if(!empty($x['photo_url'])):?><img class="photo" src="<?=e($x['photo_url'])?>" onerror="this.style.display='none'"><?php endif;?><div class="name"><?=e($x['display_name'])?></div><div class="small"><?=!empty($x['bib_number'])?'BIB '.(int)$x['bib_number']:'BIB UNASSIGNED'?><?php if(!empty($x['country'])):?> · <span class="flag"><?=e($flag)?></span> <?=e($x['country'])?><?php endif;?></div></div><?php endforeach;endif;?></div></div></div></body></html>